create extension if not exists pgcrypto;
create type public.user_role as enum ('customer','admin');
create type public.order_status as enum ('pending','processing','shipped','completed','cancelled');
create table public.categories(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,description text,image_url text,created_at timestamptz not null default now());
create table public.products(id uuid primary key default gen_random_uuid(),category_id uuid references public.categories(id) on delete set null,name text not null,slug text not null unique,description text not null,short_description text,price numeric(12,2) not null check(price>=0),old_price numeric(12,2) check(old_price>=0),stock integer not null default 0 check(stock>=0),image_url text,is_active boolean not null default true,is_featured boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.product_images(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id) on delete cascade,url text not null,sort_order integer not null default 0,created_at timestamptz not null default now());
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,name text,phone text,role public.user_role not null default 'customer',created_at timestamptz not null default now());
create table public.favorites(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,product_id uuid not null references public.products(id) on delete cascade,created_at timestamptz not null default now(),unique(user_id,product_id));
create table public.orders(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete set null,customer_name text not null,customer_email text not null,customer_phone text not null,address text not null,city text not null,comment text,status public.order_status not null default 'pending',subtotal numeric(12,2) not null check(subtotal>=0),total numeric(12,2) not null check(total>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,product_id uuid references public.products(id) on delete set null,product_name text not null,price numeric(12,2) not null check(price>=0),quantity integer not null check(quantity>0),created_at timestamptz not null default now());
create index products_category_idx on public.products(category_id);create index products_active_created_idx on public.products(is_active,created_at desc);create index order_items_order_idx on public.order_items(order_id);create index orders_user_idx on public.orders(user_id);
create function public.is_admin() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.profiles where id=auth.uid() and role='admin')$$;
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.profiles(id,name) values(new.id,new.raw_user_meta_data->>'name');return new;end$$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create function public.touch_updated_at() returns trigger language plpgsql as $$begin new.updated_at=now();return new;end$$;
create trigger products_updated before update on public.products for each row execute procedure public.touch_updated_at();create trigger orders_updated before update on public.orders for each row execute procedure public.touch_updated_at();
alter table public.categories enable row level security;alter table public.products enable row level security;alter table public.product_images enable row level security;alter table public.profiles enable row level security;alter table public.favorites enable row level security;alter table public.orders enable row level security;alter table public.order_items enable row level security;
create policy "categories public read" on public.categories for select using(true);create policy "active products public read" on public.products for select using(is_active or public.is_admin());create policy "images public read" on public.product_images for select using(exists(select 1 from public.products p where p.id=product_id and(p.is_active or public.is_admin())));
create policy "profile self read" on public.profiles for select using(id=auth.uid() or public.is_admin());create policy "profile self update" on public.profiles for update using(id=auth.uid()) with check(id=auth.uid() and role=(select role from public.profiles where id=auth.uid()));
create policy "favorites own read" on public.favorites for select using(user_id=auth.uid());create policy "favorites own insert" on public.favorites for insert with check(user_id=auth.uid());create policy "favorites own delete" on public.favorites for delete using(user_id=auth.uid());
create policy "orders own read" on public.orders for select using(user_id=auth.uid() or public.is_admin());create policy "items own read" on public.order_items for select using(exists(select 1 from public.orders o where o.id=order_id and(o.user_id=auth.uid() or public.is_admin())));
create policy "admin categories all" on public.categories for all using(public.is_admin()) with check(public.is_admin());create policy "admin products all" on public.products for all using(public.is_admin()) with check(public.is_admin());create policy "admin images all" on public.product_images for all using(public.is_admin()) with check(public.is_admin());create policy "admin orders update" on public.orders for update using(public.is_admin()) with check(public.is_admin());
insert into storage.buckets(id,name,public) values('products','products',true) on conflict do nothing;
create policy "product images public storage" on storage.objects for select using(bucket_id='products');create policy "admins manage product storage" on storage.objects for all using(bucket_id='products' and public.is_admin()) with check(bucket_id='products' and public.is_admin());
create function public.create_order(customer_name text,customer_email text,customer_phone text,shipping_address text,shipping_city text,order_comment text,cart_items jsonb) returns uuid language plpgsql security definer set search_path='' as $$declare new_id uuid;calculated numeric(12,2);item jsonb;p public.products%rowtype;begin if jsonb_array_length(cart_items)=0 then raise exception 'Cart is empty';end if;calculated:=0;for item in select * from jsonb_array_elements(cart_items) loop select * into p from public.products where id=(item->>'product_id')::uuid and is_active for update;if p.id is null or p.stock<(item->>'quantity')::int then raise exception 'Product unavailable';end if;calculated:=calculated+p.price*(item->>'quantity')::int;end loop;insert into public.orders(user_id,customer_name,customer_email,customer_phone,address,city,comment,subtotal,total) values(auth.uid(),customer_name,customer_email,customer_phone,shipping_address,shipping_city,order_comment,calculated,calculated) returning id into new_id;for item in select * from jsonb_array_elements(cart_items) loop select * into p from public.products where id=(item->>'product_id')::uuid;insert into public.order_items(order_id,product_id,product_name,price,quantity) values(new_id,p.id,p.name,p.price,(item->>'quantity')::int);update public.products set stock=stock-(item->>'quantity')::int where id=p.id;end loop;return new_id;end$$;grant execute on function public.create_order(text,text,text,text,text,text,jsonb) to anon,authenticated;
